import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
tok = None
log = []
def get_token():
    global tok
    while True:
        try:
            r = urllib.request.urlopen(urllib.request.Request(BASE + "/token", data=b"", method="POST"), timeout=30)
            tok = json.load(r)["token"]; return
        except urllib.error.HTTPError as e:
            wait(e, "/token")
        except Exception as e:
            log.append(("token-exc", str(e))); time.sleep(1)
def wait(e, path):
    ra = e.headers.get("Retry-After")
    log.append((e.code, path, ra, e.read()[:200].decode(errors="replace")))
    time.sleep(float(ra) if ra else 1)
def get(path):
    if tok is None: get_token()
    while True:
        try:
            req = urllib.request.Request(BASE + path, headers={"Authorization": "Bearer " + tok})
            r = urllib.request.urlopen(req, timeout=30)
            body = r.read()
            return 200, json.loads(body)
        except urllib.error.HTTPError as e:
            if e.code == 401 or e.code == 403:
                log.append((e.code, path, None, e.read()[:200].decode(errors="replace"))); get_token()
            elif e.code == 404:
                return 404, None
            else:
                wait(e, path)
        except Exception as e:
            log.append(("exc", path, str(e))); time.sleep(1)

pages = {}
p = 1
_, first = get("/orders?page=1")
pages[1] = first
total = first["total_pages"]
for n in range(2, total + 1):
    code, d = get(f"/orders?page={n}")
    pages[n] = d
# sanity: next chain
nexts = {n: pages[n]["next"] for n in pages}
cust_ids = sorted({o["customer_id"] for d in pages.values() for o in d["items"]})
custs = {}
for c in cust_ids:
    code, d = get(f"/customers/{c}")
    custs[c] = d
json.dump({"pages": pages, "custs": custs, "log": log, "nexts": nexts}, open("/tmp/recon/raw.json", "w"), indent=1)
print("pages", len(pages), "custs", len(custs), "log entries", len(log))
for l in log[:40]: print(l)
EOF
python3 -I /tmp/recon/fetch.py

